import{_ as o,o as t,c as d,a3 as c}from"./chunks/framework.DAK02U1-.js";const _=JSON.parse('{"title":"钩子机制（inject runtime 实现）","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"钩子机制（inject runtime 实现） | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/zh/catter/design/hook-mechanism"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"zh_CN"}],["link",{"rel":"canonical","href":"https://docs.clice.io/zh/catter/design/hook-mechanism"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/catter/design/hook-mechanism"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/catter/design/hook-mechanism"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/catter/design/hook-mechanism"}]]},"headers":[],"relativePath":"zh/catter/design/hook-mechanism.md","filePath":"zh/catter/design/hook-mechanism.md","lastUpdated":1792989239000}'),a={name:"zh/catter/design/hook-mechanism.md"};function r(i,e,n,s,l,p){return t(),d("div",null,[...e[0]||(e[0]=[c(`<h1 id="钩子机制-inject-runtime-实现" tabindex="-1">钩子机制（inject runtime 实现） <a class="header-anchor" href="#钩子机制-inject-runtime-实现" aria-label="Permalink to &quot;钩子机制（inject runtime 实现）&quot;">​</a></h1><blockquote><p>本文描述 <strong>inject runtime</strong> 的底层实现，handler 作者通常不需要阅读。它解答的是&quot;命令是如何被捕获的&quot;这一平台细节；handler 关心的能力与限制见<a href="./runtime">运行机制</a>。</p></blockquote><p>钩子是 inject runtime 的捕获载体：一个共享库，被加载到构建系统生成的每个进程中。它的唯一职责是拦截进程创建调用，并将其重写，使每个子进程都通过 <code>catter-proxy</code> 中转，而非直接执行。</p><p>钩子的实现完全依赖于平台特性。Unix 和 Windows 使用了截然不同的拦截技术。</p><h2 id="unix-linux-与-macos-基于-ld-preload-的拦截" tabindex="-1">Unix（Linux 与 macOS）-- 基于 LD_PRELOAD 的拦截 <a class="header-anchor" href="#unix-linux-与-macos-基于-ld-preload-的拦截" aria-label="Permalink to &quot;Unix（Linux 与 macOS）-- 基于 LD_PRELOAD 的拦截&quot;">​</a></h2><p>Unix 钩子是通过动态链接器的预加载机制加载的共享库：</p><ul><li><strong>Linux</strong>: <code>libcatter-hook-unix.so</code>，通过 <code>LD_PRELOAD</code> 加载</li><li><strong>macOS</strong>: <code>libcatter-hook-unix.dylib</code>，通过 <code>DYLD_INSERT_LIBRARIES</code> 加载</li></ul><h3 id="被拦截的函数" tabindex="-1">被拦截的函数 <a class="header-anchor" href="#被拦截的函数" aria-label="Permalink to &quot;被拦截的函数&quot;">​</a></h3><p>钩子替换了所有用于创建新进程的标准 POSIX 函数：</p><p><strong>exec 系列</strong>:</p><ul><li><code>execve()</code>、<code>execv()</code></li><li><code>execvpe()</code>、<code>execvp()</code>、<code>execvP()</code></li><li><code>execl()</code>、<code>execlp()</code>、<code>execle()</code></li></ul><p><strong>posix_spawn 系列</strong>:</p><ul><li><code>posix_spawn()</code></li><li><code>posix_spawnp()</code></li></ul><p>在 Linux 上，钩子使用 <code>dlsym(RTLD_NEXT, &quot;execve&quot;)</code> 从加载顺序中的下一个库获取原始函数指针，然后提供一个签名相同的替换函数。当替换函数被调用时，钩子可以检查和修改参数，然后选择性地调用原始函数。</p><p>在 macOS 上，钩子使用 <code>DYLD_INTERPOSE</code> 宏在 dyld 层面替换函数，这是该平台上的首选技术。</p><p>dyld 会终止无法加载插入库的程序，而钩子是按 catter 自身的架构构建的，Apple 自带的工具（arm64e）和在 Rosetta 下运行的 Intel 程序（x86_64）都不以这个架构运行。插入钩子之前，<code>catter-proxy</code> 先向 dyld 询问程序以哪种架构运行（<code>macho_best_slice</code>；脚本按其解释器计）：架构不同的程序不带钩子运行，它启动的进程不会被捕获。开启系统完整性保护（SIP）时，dyld 同样会从 Apple 的工具中去掉钩子，因此构建只能捕获到它所运行的 Apple 工具为止：<code>/usr/bin/make</code>，或 Ninja 用来运行每条命令的 <code>/bin/sh</code>。</p><h3 id="核心类" tabindex="-1">核心类 <a class="header-anchor" href="#核心类" aria-label="Permalink to &quot;核心类&quot;">​</a></h3><p>钩子由一组协作的类实现：</p><ul><li><strong><code>Session</code></strong> -- 从环境变量中读取并存储会话信息（代理路径、自身命令 ID 和会话的管道）。</li><li><strong><code>find_program()</code></strong>（kotatsu）-- 像 exec 函数那样，在 <code>PATH</code> 或当前目录中查找目标可执行文件；程序不存在或无法运行时，像原调用一样失败。</li><li><strong><code>Command</code> / <code>build_proxy_command()</code></strong> -- 构造重写后的代理命令，将 <code>catter-proxy</code> 替换原始可执行文件。</li><li><strong><code>SanitizedEnv</code> / <code>sanitize_environment()</code></strong> -- 在调用真正的 <code>execve</code> 之前清理环境。移除 catter 相关变量，并从预加载变量中剥离钩子库。</li><li><strong><code>Executor</code></strong> -- 协调整个拦截过程。验证会话、解析可执行文件、构造代理命令、清理环境、调用原始函数；并持有真实 <code>execve</code> / <code>posix_spawn</code> 的函数指针（早期独立的 <code>Linker</code> 类已并入其中）。</li></ul><h3 id="钩子初始化" tabindex="-1">钩子初始化 <a class="header-anchor" href="#钩子初始化" aria-label="Permalink to &quot;钩子初始化&quot;">​</a></h3><p>钩子库通过动态链接器的构造函数机制（<code>on_load</code>，<code>__attribute__((constructor))</code>）加载。初始化期间，库会：</p><ol><li>设置日志（调试构建下输出到 catter 数据目录下的 <code>log/catter-hook.log</code>）</li><li>调用 <code>Executor::init()</code>：从环境变量中读取会话状态，并解析真实的 <code>execve</code> / <code>posix_spawn</code> 函数指针（Linux 上经 <code>dlsym(RTLD_NEXT, ...)</code>，macOS 上直接引用系统符号）</li></ol><h3 id="环境变量" tabindex="-1">环境变量 <a class="header-anchor" href="#环境变量" aria-label="Permalink to &quot;环境变量&quot;">​</a></h3><p>钩子从以下环境变量中读取会话信息，这些变量由代理在启动构建命令时设置：</p><table tabindex="0"><thead><tr><th>变量</th><th>用途</th></tr></thead><tbody><tr><td><code>__key_catter_proxy_path_v1</code></td><td><code>catter-proxy</code> 二进制文件的绝对路径</td></tr><tr><td><code>__key_catter_command_id_v1</code></td><td>父进程的会话 ID</td></tr><tr><td><code>__key_catter_ipc_v1</code></td><td>catter 会话的管道</td></tr></tbody></table><h3 id="拦截流程" tabindex="-1">拦截流程 <a class="header-anchor" href="#拦截流程" aria-label="Permalink to &quot;拦截流程&quot;">​</a></h3><p>当任何进程创建函数被调用时（例如 <code>execve(&quot;/usr/bin/g++&quot;, argv, envp)</code>）：</p><ol><li><p>进入钩子的替换函数。</p></li><li><p><strong><code>Executor</code></strong> 验证会话。如果会话无效（缺少环境变量），它会构建一个错误命令，将问题报告给守护进程。</p></li><li><p><strong><code>Executor</code></strong> 用 kotatsu 的 <code>find_program()</code> 查找目标可执行文件。对于 <code>execvp()</code> 和 <code>execvpe()</code> 等函数，它会搜索 <code>PATH</code> 中的目录。对于 <code>execve()</code>，不含 <code>/</code> 的路径从当前目录查找。</p></li><li><p><strong><code>Command</code></strong>（<code>build_proxy_command()</code>）构造代理命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;proxy_path&gt; -p &lt;self_id&gt; --exec &lt;resolved_path&gt; --ipc &lt;pipe&gt; -- &lt;original_argv...&gt;</span></span></code></pre></div><p>原始的 <code>argv[0]</code> 及所有后续参数保留在 <code>--</code> 分隔符之后。</p></li><li><p><strong><code>SanitizedEnv</code></strong>（<code>sanitize_environment()</code>）修改环境数组：</p><ul><li>移除 <code>__key_catter_proxy_path_v1</code>、<code>__key_catter_command_id_v1</code> 和 <code>__key_catter_ipc_v1</code></li><li>从 <code>LD_PRELOAD</code>（或 <code>DYLD_INSERT_LIBRARIES</code>）中剥离钩子库名称</li><li>如果剥离后 <code>LD_PRELOAD</code> 变为空，则将其完全移除</li></ul></li><li><p><strong><code>Executor</code></strong> 使用重写后的命令调用<strong>真正的</strong> <code>execve()</code>（通过初始化时解析得到的函数指针）。</p></li><li><p>如果 <code>execve</code> 成功，当前进程镜像被替换，函数不会返回。如果失败，钩子恢复 <code>errno</code> 并将错误返回给调用者。</p></li></ol><h3 id="为什么要清理环境" tabindex="-1">为什么要清理环境？ <a class="header-anchor" href="#为什么要清理环境" aria-label="Permalink to &quot;为什么要清理环境？&quot;">​</a></h3><p>这一步至关重要。如果在启动 <code>catter-proxy</code> 时钩子库仍留在 <code>LD_PRELOAD</code> 中：</p><ol><li><code>catter-proxy</code> 本身会被钩住</li><li>当代理尝试执行实际的编译器时，钩子会拦截该调用</li><li>钩子会将其重写为启动另一个 <code>catter-proxy</code></li><li>这将造成<strong>无限递归</strong></li></ol><p>通过从 <code>LD_PRELOAD</code> 中剥离钩子，代理可以不受拦截地执行。代理仅在以 <code>INJECT</code> 动作启动命令时才重新添加 <code>LD_PRELOAD</code>，确保钩子仅挂载到正确的进程上。</p><h3 id="递归钩子" tabindex="-1">递归钩子 <a class="header-anchor" href="#递归钩子" aria-label="Permalink to &quot;递归钩子&quot;">​</a></h3><p>由于 <code>LD_PRELOAD</code> 通过环境变量被子进程继承，拦截是自动递归的。考虑如下构建场景：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make</span></span>
<span class="line"><span>  -&gt; sh -c &quot;gcc main.c -o main&quot;</span></span>
<span class="line"><span>     -&gt; gcc main.c -o main</span></span>
<span class="line"><span>        -&gt; cc1 main.c -o main.s</span></span>
<span class="line"><span>        -&gt; as main.s -o main.o</span></span>
<span class="line"><span>        -&gt; ld main.o -o main</span></span></code></pre></div><p>这棵进程树中的每个进程都继承了 <code>LD_PRELOAD</code>，因此都会被钩住。每次调用都会经过 <code>catter-proxy</code>，由守护进程决定如何处理。构建系统完全无法感知到拦截的存在。</p><hr><h2 id="windows-dll-注入与-api-钩子" tabindex="-1">Windows -- DLL 注入与 API 钩子 <a class="header-anchor" href="#windows-dll-注入与-api-钩子" aria-label="Permalink to &quot;Windows -- DLL 注入与 API 钩子&quot;">​</a></h2><p>Windows 钩子使用了与 Unix 完全不同的方法，因为 Windows 没有 <code>LD_PRELOAD</code> 的等价机制。catter 结合使用了：</p><ol><li><strong>DLL 注入</strong> -- 将钩子库加载到目标进程中</li><li><strong>基于 <a href="https://github.com/microsoft/Detours" target="_blank" rel="noreferrer">Microsoft Detours</a> 的 API 钩子</strong> -- 在这些进程内拦截 <code>CreateProcess</code> 调用</li></ol><h3 id="钩子-dll" tabindex="-1">钩子 DLL <a class="header-anchor" href="#钩子-dll" aria-label="Permalink to &quot;钩子 DLL&quot;">​</a></h3><p>进程只会加载与自身架构相同的 DLL，因此每种架构各有一个钩子 DLL，都安装在 <code>catter-proxy.exe</code> 所在的目录：</p><table tabindex="0"><thead><tr><th>DLL</th><th>加载到</th></tr></thead><tbody><tr><td><code>catter-hook-x64.dll</code></td><td>x64 进程、在 ARM64 上模拟运行的 x64 进程、ARM64EC 程序</td></tr><tr><td><code>catter-hook-arm64.dll</code></td><td>原生 ARM64 进程</td></tr></tbody></table><p>catter 的每个 Windows 版本都同时带有这两个 DLL：在 Windows on ARM 上，一次构建中既有原生 ARM64 工具，也有模拟运行的 x64 工具。32 位（x86）进程目前还没有对应的钩子 DLL：它不加载钩子直接运行，与没有 catter 时一样，它启动的命令也不会被捕获。catter-proxy 会记录一条警告，写明是哪个程序。</p><p>两个 DLL 构建时都不启用 AddressSanitizer，并把 C++ 运行时链接进 DLL 本身，只导入 Windows 自带的 DLL（包括 UCRT）：它们运行在构建的每个进程中，这些进程未必带有其他运行时 DLL；而且 Detours 在地址空间中搜索时会读到 ASan 的影子内存（shadow memory）。</p><h3 id="环境变量-1" tabindex="-1">环境变量 <a class="header-anchor" href="#环境变量-1" aria-label="Permalink to &quot;环境变量&quot;">​</a></h3><table tabindex="0"><thead><tr><th>变量</th><th>用途</th></tr></thead><tbody><tr><td><code>CATTER_IPC_ID</code></td><td>父进程的会话 ID</td></tr><tr><td><code>CATTER_IPC_PIPE</code></td><td>catter 会话的管道</td></tr><tr><td><code>CATTER_PROXY_PATH</code></td><td><code>catter-proxy.exe</code> 的绝对路径</td></tr></tbody></table><h3 id="dll-注入过程" tabindex="-1">DLL 注入过程 <a class="header-anchor" href="#dll-注入过程" aria-label="Permalink to &quot;DLL 注入过程&quot;">​</a></h3><p>当 <code>catter-proxy</code>（注入模式）需要启动挂载了钩子的构建命令时：</p><ol><li><p><strong>以挂起状态创建目标进程</strong>。代理用 kotatsu 的 <code>kota::sys::spawn</code> 启动它，其 <code>windows_before_start</code> 回调拿到已创建的进程：进程已在自己的 job 对象中，主线程尚未运行。</p></li><li><p><strong>设置环境变量</strong>。<code>CATTER_IPC_ID</code>、<code>CATTER_IPC_PIPE</code> 和 <code>CATTER_PROXY_PATH</code> 在创建进程前通过环境块传入目标进程。</p></li><li><p><strong>确定进程的架构</strong>。<code>GetProcessInformation(ProcessMachineTypeInfo)</code> 给出进程所运行代码的机器类型：在 ARM64 上模拟运行的 x64 进程和 ARM64EC 进程得到的都是 x64，而 <code>IsWow64Process2</code> 无法把它们与原生 ARM64 进程区分开。Windows 10 没有 <code>ProcessMachineTypeInfo</code>，也不支持模拟 x64，在那里由 <code>IsWow64Process2</code> 给出架构。</p></li><li><p><strong>把钩子 DLL 加入进程的导入表</strong>。<code>DetourUpdateProcessWithDll()</code> 把对应架构的 DLL 加入挂起的可执行文件的导入表，这样加载器会在程序自身的任何代码运行之前映射它。加载器按进程自己的 ANSI 代码页读取导入表里的 DLL 路径，而程序可以把这个代码页设为 UTF-8，所以路径必须是纯 ASCII：含非 ASCII 字符的路径改用它的 8.3 短文件名；在不保留短文件名的卷上，则改用复制到 catter 数据目录中的那份 DLL。</p></li><li><p><strong>恢复主线程</strong>。回调返回后，<code>spawn</code> 恢复主线程。加载器把钩子 DLL 与程序的其他导入项一同映射，钩子在程序入口点运行之前就已激活。</p></li></ol><h3 id="被钩住的-windows-api" tabindex="-1">被钩住的 Windows API <a class="header-anchor" href="#被钩住的-windows-api" aria-label="Permalink to &quot;被钩住的 Windows API&quot;">​</a></h3><p>钩子 DLL 在 <code>DLL_PROCESS_ATTACH</code> 期间用 Detours 为以下函数安装钩子，全部在同一个事务中完成：</p><ul><li><strong><code>CreateProcessA()</code></strong> -- ANSI 版本的进程创建函数</li><li><strong><code>CreateProcessW()</code></strong> -- 宽字符版本的进程创建函数</li></ul><p>程序以其他账户的令牌（token）启动的进程（<code>CreateProcessAsUser</code>、<code>CreateProcessWithTokenW</code>、<code>CreateProcessWithLogonW</code>）不带钩子运行，也不会被捕获：要捕获它，<code>catter-proxy</code> 也得以该令牌运行，而那个账户可能无法启动它，也可能访问不到会话的管道。</p><p>Detours 的工作原理：</p><ol><li>保存目标函数的前几条指令</li><li>将其覆写为跳转到替代函数的指令</li><li>提供一个 trampoline（跳板），包含保存的指令及跳回原函数的跳转，使原始函数仍可被调用</li></ol><h3 id="钩子替代逻辑" tabindex="-1">钩子替代逻辑 <a class="header-anchor" href="#钩子替代逻辑" aria-label="Permalink to &quot;钩子替代逻辑&quot;">​</a></h3><p>当被钩住的进程调用 <code>CreateProcessA</code> 或 <code>CreateProcessW</code> 时：</p><ol><li><p><strong>提取命令行</strong>。钩子读取 <code>lpApplicationName</code> 和 <code>lpCommandLine</code>。</p></li><li><p><strong>解析程序</strong>。钩子用 <code>resolve_program()</code> 解析：<code>lpApplicationName</code> 从当前目录补全为绝对路径；没有它时，取命令行的第一个词，按 <code>CreateProcess</code> 的方式查找（kotatsu 的 <code>find_create_process_program</code>：程序所在目录、当前目录、系统目录、Windows 目录，最后是 <code>PATH</code>）。</p></li><li><p><strong>重写命令行</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{proxy_path} -p {ipc_id} --exec {resolved_path} --ipc {pipe} -- {original_cmdline}</span></span></code></pre></div><p><code>lpApplicationName</code> 被设为 <code>nullptr</code>，使 <code>CreateProcess</code> 正常解析命令行。</p></li><li><p><strong>通过 Detours trampoline 调用原始 <code>CreateProcess</code></strong>，传入修改后的命令行。</p></li></ol><h3 id="与-unix-的关键区别" tabindex="-1">与 Unix 的关键区别 <a class="header-anchor" href="#与-unix-的关键区别" aria-label="Permalink to &quot;与 Unix 的关键区别&quot;">​</a></h3><p>在 Unix 上，<code>LD_PRELOAD</code> 是一个由所有子进程自动继承的环境变量。钩子默认具有&quot;传染性&quot; -- 每个子进程都会被钩住。</p><p>在 Windows 上没有这样的机制。钩子 DLL 必须显式注入到每个新进程中。这通过以下方式实现：</p><ol><li>钩子的 <code>CreateProcess</code> 替代函数拦截每次进程创建</li><li>将命令重写为通过 <code>catter-proxy</code> 中转</li><li>当代理决定以 <code>INJECT</code> 动作执行时，它对新进程执行 DLL 注入（创建挂起、注入、恢复）</li></ol><p>这意味着代理负责在每一代子进程中重新注入钩子，维持递归拦截链。链上可以交替出现不同架构的进程：每个进程都会得到与自身架构对应的钩子 DLL。</p><h3 id="dll-生命周期" tabindex="-1">DLL 生命周期 <a class="header-anchor" href="#dll-生命周期" aria-label="Permalink to &quot;DLL 生命周期&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DLL_PROCESS_ATTACH:</span></span>
<span class="line"><span>  DetourRestoreAfterWith()   -- Restore the import table catter-proxy changed</span></span>
<span class="line"><span>  DetourTransactionBegin()</span></span>
<span class="line"><span>  DetourAttach(...)          -- Hook CreateProcessA and CreateProcessW</span></span>
<span class="line"><span>  DetourTransactionCommit()  -- Activate all hooks at once</span></span></code></pre></div><p>在 attach 阶段调用 <code>DisableThreadLibraryCalls()</code> 以抑制 <code>DLL_THREAD_ATTACH</code> 和 <code>DLL_THREAD_DETACH</code> 通知，减少运行开销。该 DLL 是可执行文件的导入项，只随进程一起卸载，因此 <code>DLL_PROCESS_DETACH</code> 时没有需要撤销的操作。它导出序号为 1 的符号，凡是由 Detours 注入的 DLL 都必须如此。</p><h2 id="平台对比" tabindex="-1">平台对比 <a class="header-anchor" href="#平台对比" aria-label="Permalink to &quot;平台对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方面</th><th>Linux</th><th>macOS</th><th>Windows</th></tr></thead><tbody><tr><td>钩子库</td><td><code>libcatter-hook-unix.so</code></td><td><code>libcatter-hook-unix.dylib</code></td><td><code>catter-hook-{x64,arm64}.dll</code></td></tr><tr><td>注入方式</td><td><code>LD_PRELOAD</code> 环境变量</td><td><code>DYLD_INSERT_LIBRARIES</code> 环境变量</td><td><code>DetourUpdateProcessWithDll</code></td></tr><tr><td>函数替换</td><td><code>dlsym(RTLD_NEXT, ...)</code></td><td><code>DYLD_INTERPOSE</code> 宏</td><td>Detours trampoline 钩子</td></tr><tr><td>拦截的 API</td><td><code>execve</code>、<code>execvp</code>、<code>posix_spawn</code> 等</td><td>与 Linux 相同</td><td><code>CreateProcessA</code>、<code>CreateProcessW</code></td></tr><tr><td>递归钩子</td><td>自动（环境变量继承）</td><td>自动（环境变量继承）</td><td>显式（每个进程重新注入 DLL）</td></tr><tr><td>会话环境变量</td><td><code>__key_catter_proxy_path_v1</code>、<code>__key_catter_command_id_v1</code></td><td>与 Linux 相同</td><td><code>CATTER_PROXY_PATH</code>、<code>CATTER_IPC_ID</code></td></tr></tbody></table>`,69)])])}const u=o(a,[["render",r]]);export{_ as __pageData,u as default};
